writeFile(`business/index_${lang}.json`, {
	"bitcoin_is_good_for_business": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0628\u0631\u0627\u06CC \u06A9\u0633\u0628\u200C\u0648\u06A9\u0627\u0631 \u0645\u0641\u06CC\u062F \u0627\u0633\u062A",
	"biz_header": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0628\u0631\u0627\u06CC \u06A9\u0633\u0628\u200C\u0648\u06A9\u0627\u0631 \u0645\u0641\u06CC\u062F \u0627\u0633\u062A",
	"biz_s1": "\u06A9\u0627\u0631\u0645\u0632\u062F\u0647\u0627\u06CC \u06A9\u0645 \u0628\u062F\u0648\u0646 \u062D\u062F\u0627\u0642\u0644",
	"biz_s1_c1": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0628\u0647 \u0634\u0645\u0627 \u0627\u0645\u06A9\u0627\u0646 \u0645\u06CC\u200C\u062F\u0647\u062F \u067E\u0631\u062F\u0627\u062E\u062A\u200C\u0647\u0627 \u0631\u0627 \u0645\u0633\u062A\u0642\u06CC\u0645\u0627\u064B \u0627\u0632 \u0645\u0634\u062A\u0631\u06CC\u0627\u0646 \u062E\u0648\u062F \u062F\u0631\u06CC\u0627\u0641\u062A \u06A9\u0646\u06CC\u062F\u060C \u062F\u0631\u0633\u062A \u0645\u0627\u0646\u0646\u062F \u067E\u0648\u0644 \u0646\u0642\u062F. \u0634\u0628\u06A9\u0647 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0628\u062F\u0648\u0646 \u0648\u0627\u0633\u0637\u0647\u200C\u0647\u0627\u06CC\u06CC \u0645\u0627\u0646\u0646\u062F \u0628\u0627\u0646\u06A9\u200C\u0647\u0627 \u0648 \u0634\u0631\u06A9\u062A\u200C\u0647\u0627\u06CC \u06A9\u0627\u0631\u062A \u0627\u0639\u062A\u0628\u0627\u0631\u06CC \u06A9\u0647 \u06A9\u0627\u0631\u0645\u0632\u062F\u0647\u0627\u06CC \u06AF\u0632\u0627\u0641 \u0645\u06CC\u200C\u06AF\u06CC\u0631\u0646\u062F \u06A9\u0627\u0631 \u0645\u06CC\u200C\u06A9\u0646\u062F.",
	"biz_s2": "\u062A\u0633\u0648\u06CC\u0647 \u0641\u0648\u0631\u06CC",
	"biz_s2_c1": "\u062F\u0631\u0633\u062A \u0645\u0627\u0646\u0646\u062F \u067E\u0648\u0644 \u0646\u0642\u062F\u060C \u067E\u0631\u062F\u0627\u062E\u062A\u200C\u0647\u0627\u06CC \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0641\u0648\u0631\u0627\u064B \u062A\u0633\u0648\u06CC\u0647 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F. \u0646\u06CC\u0627\u0632\u06CC \u0646\u06CC\u0633\u062A \u0645\u0646\u062A\u0638\u0631 \u0634\u0631\u06A9\u062A \u06A9\u0627\u0631\u062A \u0627\u0639\u062A\u0628\u0627\u0631\u06CC \u06CC\u0627 \u0628\u0627\u0646\u06A9 \u0628\u0645\u0627\u0646\u06CC\u062F \u062A\u0627 \u0628\u0647 \u0634\u0645\u0627 \u067E\u0631\u062F\u0627\u062E\u062A \u06A9\u0646\u062F. \u062F\u0631 \u0639\u0648\u0636\u060C \u0641\u0648\u0631\u0627\u064B \u067E\u0648\u0644 \u062E\u0648\u062F \u0631\u0627 \u062F\u0631\u06CC\u0627\u0641\u062A \u0645\u06CC\u200C\u06A9\u0646\u06CC\u062F.",
	"biz_s3": "\u0628\u062F\u0648\u0646 \u0628\u0627\u0632\u06AF\u0634\u062A \u06CC\u0627 \u06A9\u0644\u0627\u0647\u0628\u0631\u062F\u0627\u0631\u06CC",
	"biz_s3_c1": "\u0686\u0648\u0646 \u067E\u0631\u062F\u0627\u062E\u062A\u200C\u0647\u0627\u06CC \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0645\u0633\u062A\u0642\u06CC\u0645\u0627\u064B \u0628\u06CC\u0646 \u0634\u0645\u0627 \u0648 \u0645\u0634\u062A\u0631\u06CC\u0627\u0646\u062A\u0627\u0646 \u0627\u0646\u062C\u0627\u0645 \u0645\u06CC\u200C\u0634\u0648\u062F\u060C \u063A\u06CC\u0631\u0645\u0645\u06A9\u0646 \u0627\u0633\u062A \u06A9\u0633\u06CC \u067E\u0648\u0644 \u0634\u0645\u0627 \u0631\u0627 \u0628\u0631\u06AF\u0631\u062F\u0627\u0646\u062F.",
	"biz_s3_c2": "\u0627\u0645\u06A9\u0627\u0646 \u0627\u0631\u0633\u0627\u0644 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u062C\u0639\u0644\u06CC \u062F\u0631 \u0634\u0628\u06A9\u0647 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0648\u062C\u0648\u062F \u0646\u062F\u0627\u0631\u062F\u060C \u0628\u0647 \u0627\u06CC\u0646 \u0645\u0639\u0646\u06CC \u06A9\u0647 \u0647\u0631\u06AF\u0632 \u0646\u06AF\u0631\u0627\u0646 \u062A\u0631\u0627\u06A9\u0646\u0634\u200C\u0647\u0627\u06CC \u062A\u0642\u0644\u0628\u06CC \u06A9\u0647 \u0628\u0647 \u06A9\u0633\u0628\u200C\u0648\u06A9\u0627\u0631 \u0634\u0645\u0627 \u0636\u0631\u0631 \u0628\u0632\u0646\u062F \u0646\u062E\u0648\u0627\u0647\u06CC\u062F \u0628\u0648\u062F.",
	"biz_s4": "\u0645\u0634\u062A\u0631\u06CC\u0627\u0646 \u0628\u06CC\u0634\u062A\u0631\u06CC \u0628\u0647 \u062F\u0633\u062A \u0622\u0648\u0631\u06CC\u062F",
	"biz_s4_c1": "\u0645\u06CC\u0644\u06CC\u0648\u0646\u200C\u0647\u0627 \u0646\u0641\u0631 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u062F\u0627\u0631\u0646\u062F \u0648 \u0645\u06CC\u200C\u062E\u0648\u0627\u0647\u0646\u062F \u0622\u0646 \u0631\u0627 \u062F\u0631 \u0645\u06A9\u0627\u0646\u200C\u0647\u0627\u06CC\u06CC \u06A9\u0647 \u0645\u06CC\u200C\u067E\u0630\u06CC\u0631\u0646\u062F \u062E\u0631\u062C \u06A9\u0646\u0646\u062F.",
	"biz_s4_c2": "\u0628\u0627 \u067E\u0630\u06CC\u0631\u0634 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646\u060C \u06A9\u0633\u0628\u200C\u0648\u06A9\u0627\u0631 \u0634\u0645\u0627 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u062F\u0631 \u0646\u0642\u0634\u0647\u200C\u0647\u0627\u06CC \u0641\u0631\u0648\u0634\u0646\u062F\u06AF\u0627\u0646 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0641\u0647\u0631\u0633\u062A \u0634\u0648\u062F \u0648 \u062A\u0628\u0644\u06CC\u063A\u0627\u062A \u0631\u0627\u06CC\u06AF\u0627\u0646 \u0628\u0631\u0627\u06CC \u0645\u0634\u062A\u0631\u06CC\u0627\u0646 \u062C\u062F\u06CC\u062F \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646\u06CC \u062F\u0631\u06CC\u0627\u0641\u062A \u06A9\u0646\u06CC\u062F.",
	"biz_s4_c3": "\u067E\u0630\u06CC\u0631\u0634 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u06F1\u06F0\u06F0\u066A \u0631\u0627\u06CC\u06AF\u0627\u0646 \u0627\u0633\u062A. \u0647\u06CC\u0686 \u0642\u0631\u0627\u0631\u062F\u0627\u062F \u06CC\u0627 \u06A9\u0627\u0631\u0645\u0632\u062F \u067E\u0646\u0647\u0627\u0646\u06CC \u0648\u062C\u0648\u062F \u0646\u062F\u0627\u0631\u062F."
});

// business/why
writeFile(`business/why_${lang}.json`, {
	"learn_why_bitcoin_is_good_for_business": "\u0628\u06CC\u0627\u0645\u0648\u0632\u06CC\u062F \u0686\u0631\u0627 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0628\u0631\u0627\u06CC \u06A9\u0633\u0628\u200C\u0648\u06A9\u0627\u0631 \u0645\u0641\u06CC\u062F \u0627\u0633\u062A",
	"why_header": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0628\u0631\u0627\u06CC \u06A9\u0633\u0628\u200C\u0648\u06A9\u0627\u0631 \u0645\u0641\u06CC\u062F \u0627\u0633\u062A",
	"why_good_for_you": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0628\u0631\u0627\u06CC \u0634\u0645\u0627 \u0647\u0645 \u0645\u0641\u06CC\u062F \u0627\u0633\u062A!",
	"why_learn_more_lowercase": "\u0628\u06CC\u0634\u062A\u0631 \u0628\u06CC\u0627\u0645\u0648\u0632\u06CC\u062F.",
	"why_s1": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u062A\u0648\u0631\u0645 \u0646\u062F\u0627\u0631\u062F",
	"why_s1_c1": "\u062A\u0648\u0631\u0645 \u0632\u0645\u0627\u0646\u06CC \u0627\u062A\u0641\u0627\u0642 \u0645\u06CC\u200C\u0627\u0641\u062A\u062F \u06A9\u0647 \u067E\u0648\u0644 \u0628\u06CC\u0634\u062A\u0631\u06CC \u0686\u0627\u067E \u06CC\u0627 \u0627\u0632 \u0647\u06CC\u0686 \u0627\u06CC\u062C\u0627\u062F \u0645\u06CC\u200C\u0634\u0648\u062F. \u0627\u06CC\u0646 \u06A9\u0627\u0631 \u067E\u0648\u0644 \u0634\u0645\u0627 \u0631\u0627 \u0628\u0627 \u06AF\u0630\u0634\u062A \u0632\u0645\u0627\u0646 \u06A9\u0645\u200C\u0627\u0631\u0632\u0634\u200C\u062A\u0631 \u0645\u06CC\u200C\u06A9\u0646\u062F.",
	"why_s1_c2": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0639\u0631\u0636\u0647 \u062B\u0627\u0628\u062A\u06CC \u062F\u0627\u0631\u062F\u060C \u0628\u0647 \u0627\u06CC\u0646 \u0645\u0639\u0646\u06CC \u06A9\u0647 \u0647\u06CC\u0686\u200C\u06A9\u0633 \u0646\u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0628\u06CC\u0634\u062A\u0631\u06CC \u0686\u0627\u067E \u06A9\u0646\u062F.",
	"why_s2": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0647\u062C\u0648\u0645 \u0628\u0627\u0646\u06A9\u06CC \u0646\u062F\u0627\u0631\u062F",
	"why_s2_c1": "\u0686\u0646\u062F\u06CC\u0646 \u0628\u0627\u0646\u06A9 \u0622\u0645\u0631\u06CC\u06A9\u0627\u06CC\u06CC \u062F\u0631 \u0633\u0627\u0644\u200C\u0647\u0627\u06CC \u0627\u062E\u06CC\u0631 \u0628\u0647 \u062F\u0644\u06CC\u0644 \u0647\u062C\u0648\u0645 \u0628\u0631\u062F\u0627\u0634\u062A \u0633\u0642\u0648\u0637 \u06A9\u0631\u062F\u0646\u062F.",
	"why_s2_c2": "\u0628\u0647 \u062C\u0627\u06CC \u0646\u06AF\u0647\u200C\u062F\u0627\u0634\u062A\u0646 \u067E\u0648\u0644 \u0634\u0645\u0627\u060C \u0628\u0627\u0646\u06A9\u200C\u0647\u0627 \u067E\u0648\u0644 \u0634\u0645\u0627 \u0631\u0627 \u0633\u0631\u0645\u0627\u06CC\u0647\u200C\u06AF\u0630\u0627\u0631\u06CC \u0648 \u0648\u0627\u0645 \u0645\u06CC\u200C\u062F\u0647\u0646\u062F. \u0627\u06AF\u0631 \u0622\u0646 \u0633\u0631\u0645\u0627\u06CC\u0647\u200C\u06AF\u0630\u0627\u0631\u06CC\u200C\u0647\u0627 \u0645\u0648\u0641\u0642 \u0646\u0628\u0627\u0634\u0646\u062F\u060C \u067E\u0648\u0644 \u06A9\u0627\u0641\u06CC \u0628\u0631\u0627\u06CC \u0628\u0627\u0632\u06AF\u0631\u062F\u0627\u0646\u062F\u0646 \u0628\u0647 \u0634\u0645\u0627 \u0646\u062F\u0627\u0631\u0646\u062F.",
	"why_s2_c3": "\u0648 \u0635\u0646\u062F\u0648\u0642 \u0628\u06CC\u0645\u0647 FDIC \u0641\u0642\u0637 \u06CC\u06A9 \u062F\u0644\u0627\u0631 \u0628\u0631\u0627\u06CC \u0647\u0631 \u06F1\u06F0\u06F0 \u062F\u0644\u0627\u0631\u06CC \u06A9\u0647 \u0628\u06CC\u0645\u0647 \u0645\u06CC\u200C\u06A9\u0646\u062F \u062F\u0627\u0631\u062F.",
	"why_s3": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0646\u06CC\u0627\u0632\u06CC \u0628\u0647 \u0627\u062C\u0627\u0632\u0647 \u0646\u062F\u0627\u0631\u062F",
	"why_s3_c1": "\u0628\u0631\u062E\u0644\u0627\u0641 \u0634\u0628\u06A9\u0647\u200C\u0647\u0627\u06CC \u0645\u0627\u0644\u06CC \u0633\u0646\u062A\u06CC\u060C \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0628\u0631\u0627\u06CC \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0646\u06CC\u0627\u0632\u06CC \u0628\u0647 \u0627\u062C\u0627\u0632\u0647 \u0646\u062F\u0627\u0631\u062F.",
	"why_s3_c2": "\u0627\u06CC\u0646 \u0628\u0647 \u0627\u06CC\u0646 \u0645\u0639\u0646\u06CC \u0627\u0633\u062A \u06A9\u0647 \u0647\u06CC\u0686\u200C\u06A9\u0633 \u0646\u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u0634\u0645\u0627 \u0631\u0627 \u0627\u0632 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0627\u0632 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0628\u0647 \u0647\u0631 \u062F\u0644\u06CC\u0644\u06CC \u0645\u0646\u0639 \u06A9\u0646\u062F. \u0627\u06CC\u0646 \u0627\u0648\u0644\u06CC\u0646 \u0634\u0628\u06A9\u0647 \u0645\u0627\u0644\u06CC \u0627\u0633\u062A \u06A9\u0647 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u0628\u062F\u0648\u0646 \u062A\u0631\u0633 \u0627\u0632 \u0633\u0627\u0646\u0633\u0648\u0631 \u06CC\u0627 \u0645\u0635\u0627\u062F\u0631\u0647 \u0627\u0632 \u0622\u0646 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u06CC\u062F.",
	"why_s4": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u062F\u0646\u06CC\u0627\u06CC\u06CC \u0628\u0647\u062A\u0631 \u0645\u06CC\u200C\u0633\u0627\u0632\u062F",
	"why_s4_c1": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u06CC\u06A9 \u0641\u0646\u0627\u0648\u0631\u06CC \u0628\u062F \u0641\u0647\u0645\u06CC\u062F\u0647 \u0634\u062F\u0647 \u0627\u0633\u062A \u06A9\u0647 \u062F\u0631 \u062D\u0627\u0644 \u0633\u0627\u062E\u062A\u0646 \u062F\u0646\u06CC\u0627\u06CC\u06CC \u0628\u0647\u062A\u0631 \u0627\u0633\u062A.",
	"why_s4_c2": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0628\u0647 \u0641\u0639\u0627\u0644\u0627\u0646 \u062D\u0642\u0648\u0642 \u0628\u0634\u0631 \u06A9\u0645\u06A9 \u06A9\u0631\u062F\u0647 \u062A\u0627 \u0628\u0631\u0627\u06CC \u0622\u0632\u0627\u062F\u06CC \u0645\u0628\u0627\u0631\u0632\u0647 \u06A9\u0646\u0646\u062F\u060C \u0627\u0646\u062A\u0634\u0627\u0631\u0627\u062A \u0645\u062A\u0627\u0646 \u062C\u0647\u0627\u0646\u06CC \u0631\u0627 \u06A9\u0627\u0647\u0634 \u062F\u0627\u062F\u0647\u060C \u067E\u0627\u0631\u06A9\u200C\u0647\u0627\u06CC \u0645\u0644\u06CC \u0631\u0627 \u0646\u062C\u0627\u062A \u062F\u0627\u062F\u0647 \u0648 \u0628\u0633\u06CC\u0627\u0631 \u0628\u06CC\u0634\u062A\u0631."
});

