	"wallets_square_note": "\u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u067E\u0631\u062F\u0627\u062E\u062A\u200C\u0647\u0627\u06CC \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0631\u0627 \u0628\u0627 \u067E\u0627\u06CC\u0627\u0646\u0647 Square PoS \u0645\u0648\u062C\u0648\u062F \u06CC\u0627 \u0627\u062F\u063A\u0627\u0645 \u0641\u0631\u0648\u0634\u06AF\u0627\u0647 \u0622\u0646\u0644\u0627\u06CC\u0646 \u062E\u0648\u062F \u0628\u067E\u0630\u06CC\u0631\u06CC\u062F. \u067E\u0630\u06CC\u0631\u0634 \u067E\u0631\u062F\u0627\u062E\u062A\u200C\u0647\u0627\u06CC \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0647\u0631\u06AF\u0632 \u0622\u0633\u0627\u0646\u200C\u062A\u0631 \u0646\u0628\u0648\u062F\u0647 \u0627\u0633\u062A.",
