	"wallets_feature_no_info": "\u0646\u06CC\u0627\u0632\u06CC \u0628\u0647 \u0627\u0637\u0644\u0627\u0639\u0627\u062A \u0646\u06CC\u0633\u062A",
	"wallets_feature_in_person": "\u0641\u0642\u0637 \u067E\u0631\u062F\u0627\u062E\u062A\u200C\u0647\u0627\u06CC \u062D\u0636\u0648\u0631\u06CC",
	"wallets_feature_settles_bitcoin": "\u062A\u0633\u0648\u06CC\u0647 \u06F1\u06F0\u06F0\u066A \u0628\u0627 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646",
