	"wallets_feature_in_person_online": "\u067E\u0631\u062F\u0627\u062E\u062A\u200C\u0647\u0627\u06CC \u062D\u0636\u0648\u0631\u06CC \u0648 \u0622\u0646\u0644\u0627\u06CC\u0646",
	"wallets_feature_settles_both": "\u062A\u0633\u0648\u06CC\u0647 \u0628\u0627 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0648 \u062F\u0644\u0627\u0631",
	"wallets_feature_multiple_employees": "\u067E\u0634\u062A\u06CC\u0628\u0627\u0646\u06CC \u0627\u0632 \u0686\u0646\u062F \u06A9\u0627\u0631\u0645\u0646\u062F (BPTs)",
	"wallets_feature_self_hosted": "\u0645\u06CC\u0632\u0628\u0627\u0646\u06CC \u0634\u062E\u0635\u06CC = \u06F0\u066A \u06A9\u0627\u0631\u0645\u0632\u062F",
	"wallets_feature_online_store": "\u0627\u062F\u063A\u0627\u0645 \u0641\u0631\u0648\u0634\u06AF\u0627\u0647 \u0622\u0646\u0644\u0627\u06CC\u0646",
	"wallets_feature_invoicing": "\u0646\u0631\u0645\u200C\u0627\u0641\u0632\u0627\u0631 \u0641\u0627\u06A9\u062A\u0648\u0631 \u0631\u0627\u06CC\u06AF\u0627\u0646",
